import { z } from 'zod';
import { requireUser, requireRole } from '@/lib/auth';
import { json, readJson, route, HttpError } from '@/lib/http';
import { logger } from '@/lib/logger';
import { audit } from '@/lib/audit';
import { getUser } from '@/repos/users';
import { createMessage, listInbox } from '@/repos/messages';

const SendBody = z.object({
  recipientUserId: z.string().min(1),
  patientId: z.string().min(1).nullable().optional(),
  subject: z.string().min(1).max(200),
  body: z.string().min(1).max(10000),
});

/** Inbox of the signed-in user (no message bodies). */
export const GET = route(async (req) => {
  const user = await requireUser(req);
  const rows = await listInbox(user.id);
  return json({
    messages: rows.map((r) => ({
      id: r.id,
      subject: r.subject,
      from: r.sender_name,
      sentAt: r.created_at,
      read: r.read_at !== null,
    })),
  });
});

/** Sends a secure message to another user of the same practice. */
export const POST = route(async (req) => {
  const user = await requireUser(req);
  requireRole(user, 'practitioner', 'patient');
  const input = SendBody.parse(await readJson(req));

  const recipient = await getUser(input.recipientUserId);
  if (!recipient || recipient.org_id !== user.orgId || recipient.id === user.id) {
    throw new HttpError(403, 'forbidden');
  }

  const id = await createMessage({
    orgId: user.orgId,
    senderUserId: user.id,
    recipientUserId: recipient.id,
    patientId: input.patientId ?? (user.role === 'patient' ? user.patientId : null),
    subject: input.subject,
    body: input.body,
  });
  await audit(user, 'message.send', 'message', id);
  logger.info('message sent', { messageId: id, senderId: user.id, recipientId: recipient.id });
  return json({ id }, 201);
});
import { requireUser } from '@/lib/auth';
import { json, route, HttpError } from '@/lib/http';
import { audit } from '@/lib/audit';
import { hasActiveAccess } from '@/repos/careTeam';
import { getPatient } from '@/repos/patients';
import { listForPatient } from '@/repos/notes';

type Ctx = { params: Promise<{ patientId: string }> };

/** Chart view for a practitioner on the patient's care team. */
export const GET = route<Ctx>(async (req, { params }) => {
  const user = await requireUser(req);
  if (user.role !== 'practitioner' || !user.practitionerId) throw new HttpError(403, 'forbidden');
  const { patientId } = await params;
  const patient = await getPatient(patientId);
  if (!patient || patient.org_id !== user.orgId) throw new HttpError(404, 'not_found');
  if (!(await hasActiveAccess(user.practitionerId, patient.id))) throw new HttpError(403, 'forbidden');

  const notes = await listForPatient(patient.id);
  await audit(user, 'chart.view', 'patient', patient.id);
  return json({
    patient: {
      id: patient.id,
      firstName: patient.first_name,
      lastName: patient.last_name,
      dateOfBirth: patient.date_of_birth,
      mrn: patient.mrn,
      reasonForCare: patient.reason_for_care,
    },
    notes: notes.map((n) => ({ id: n.id, kind: n.kind, createdAt: n.created_at, body: n.body })),
  });
});
import { describe, expect, it } from 'vitest';
import { GET, POST } from '@/app/api/messages/route';
import { call, TOKENS } from './helpers';

describe('POST /api/messages', () => {
  it('lets a practitioner message a patient of the same practice', async () => {
    const res = await call(POST, {
      method: 'POST',
      token: TOKENS.rosa,
      body: { recipientUserId: 'usr_ava', patientId: 'pt_ava', subject: 'Homework', body: 'Try the breathing exercise twice a day.' },
    });
    expect(res.status).toBe(201);
    expect(res.json.id).toMatch(/^msg_/);
  });

  it('refuses a recipient from another practice', async () => {
    const res = await call(POST, {
      method: 'POST',
      token: TOKENS.rosa,
      body: { recipientUserId: 'usr_june', subject: 'Hi', body: 'Hello' },
    });
    expect(res.status).toBe(403);
  });

  it('requires authentication', async () => {
    const res = await call(POST, { method: 'POST', body: { recipientUserId: 'usr_ava', subject: 'x', body: 'y' } });
    expect(res.status).toBe(401);
  });
});

describe('GET /api/messages', () => {
  it('lists the inbox without message bodies', async () => {
    const res = await call(GET, { token: TOKENS.ava });
    expect(res.status).toBe(200);
    expect(res.json.messages.length).toBeGreaterThan(0);
    for (const m of res.json.messages) expect(m).not.toHaveProperty('body');
  });
});
